window.appendVideoConsent=(box,id,title)=>{const panel=document.createElement('div');panel.className='video-consent';const text=document.createElement('p');text.textContent='Cette vidéo est hébergée par YouTube. La charger transmet des données à ce service et peut activer ses traceurs.';const button=document.createElement('button');button.className='button red';button.textContent='Accepter et charger la vidéo';button.addEventListener('click',()=>{const iframe=document.createElement('iframe');iframe.src='https://www.youtube-nocookie.com/embed/'+id;iframe.title=title;iframe.allowFullscreen=true;iframe.allow='encrypted-media; picture-in-picture';panel.replaceWith(iframe)});const link=document.createElement('a');link.href='https://www.youtube.com/watch?v='+id;link.textContent='Voir sur YouTube ↗';link.className='text-link';link.target='_blank';link.rel='noopener';panel.append(text,button,link);box.append(panel)};
